  ('g2-s2-fraction_of_quantity-difficult-0001', 2, 2, 'fraction_of_quantity', 'difficult', '{"whole": 24, "n1": 3, "n2": 4, "den": 12}'::jsonb, '24 mangoes are shared: 3/12 go to Group A and 4/12 go to Group B. How many mangoes are left over?', '["10", "8", "6", "18"]'::jsonb, '10', '["gave Group A''s share instead of the remainder", "gave Group B''s share instead of the remainder", "forgot to subtract Group A''s share too"]'::jsonb, 'Group A gets 6, Group B gets 8, leaving 24 - 6 - 8 = 10.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
