  ('g2-s3-ratio_scaling-easy-0001', 2, 3, 'ratio_scaling', 'easy', '{"r1": 7, "r2": 2, "mult": 5}'::jsonb, 'The ratio of red to blue marbles is 7:2. If there are 35 red marbles, how many blue marbles are there?', '["35", "10", "45", "17"]'::jsonb, '10', '["gave the red count back instead of scaling to blue", "added the red ratio part on top by mistake", "gave the total of red and blue instead of just blue"]'::jsonb, '35/7 = 5 marbles per ratio unit, so blue = 2 x 5 = 10.', NULL, '', 15, NULL, 'template-mtap-g2-v1', true),
