  ('g2-s3-ratio_scaling-average-0001', 2, 3, 'ratio_scaling', 'average', '{"r1": 6, "r2": 4, "mult": 3}'::jsonb, 'The ratio of oranges to apples is 6:4. If there are 30 fruits in all, how many are oranges?', '["21", "30", "12", "18"]'::jsonb, '18', '["gave the apple count instead of the orange count", "gave the total instead of just the orange share", "off by one ratio-unit''s worth"]'::jsonb, '30 / (6+4) = 3 fruits per unit, so oranges = 6 x 3 = 18.', NULL, '', 30, NULL, 'template-mtap-g2-v1', true),
