  ('g2-s3-ratio_scaling-difficult-0001', 2, 3, 'ratio_scaling', 'difficult', '{"r1": 7, "r2": 2, "mult": 7}'::jsonb, 'Two numbers are in the ratio 7:2. The bigger number is 35 more than the smaller. What is the bigger number?', '["49", "14", "35", "54"]'::jsonb, '49', '["gave the smaller number instead of the bigger", "gave the difference itself instead of the bigger number", "off by one ratio-unit''s worth"]'::jsonb, 'The difference 35 corresponds to 5 ratio units, so 1 unit = 7. Bigger = 7 x 7 = 49.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
